from __future__ import annotations

import uuid

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from src.backend.core.deps import get_current_user, require_any_role, require_role
from src.backend.core.roles import Role
from src.backend.db.session import get_db
from src.backend.models.user import User
from src.backend.schemas.instagram_metric import (
    InstagramMetricCreate,
    InstagramMetricListResponse,
    InstagramMetricRead,
    InstagramMetricUpdate,
)
from src.backend.services import instagram_metric_service

router = APIRouter(prefix="/api/instagram-metrics", tags=["instagram-metrics"])


@router.get("", response_model=InstagramMetricListResponse)
def list_instagram_metrics(
    _: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
) -> InstagramMetricListResponse:
    items, total = instagram_metric_service.list_instagram_metrics_service(
        db, page=page, page_size=page_size
    )
    return InstagramMetricListResponse(
        items=[InstagramMetricRead.model_validate(i) for i in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.post("", response_model=InstagramMetricRead, status_code=status.HTTP_201_CREATED)
def create_instagram_metric(
    body: InstagramMetricCreate,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> InstagramMetricRead:
    metric = instagram_metric_service.create_instagram_metric_service(db, body, current_user.id)
    return InstagramMetricRead.model_validate(metric)


@router.get("/{metric_id}", response_model=InstagramMetricRead)
def get_instagram_metric(
    metric_id: uuid.UUID,
    _: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> InstagramMetricRead:
    metric = instagram_metric_service.get_instagram_metric_service(db, metric_id)
    if not metric:
        raise HTTPException(status_code=404, detail="Instagram metric not found")
    return InstagramMetricRead.model_validate(metric)


@router.patch("/{metric_id}", response_model=InstagramMetricRead)
def update_instagram_metric(
    metric_id: uuid.UUID,
    body: InstagramMetricUpdate,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> InstagramMetricRead:
    metric = instagram_metric_service.update_instagram_metric_service(
        db, metric_id, body, current_user.id
    )
    if not metric:
        raise HTTPException(status_code=404, detail="Instagram metric not found")
    return InstagramMetricRead.model_validate(metric)


@router.delete("/{metric_id}", status_code=status.HTTP_204_NO_CONTENT, response_class=None)
def delete_instagram_metric(
    metric_id: uuid.UUID,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
):
    ok = instagram_metric_service.delete_instagram_metric_service(db, metric_id, current_user.id)
    if not ok:
        raise HTTPException(status_code=404, detail="Instagram metric not found")
    return None

from enum import StrEnum


class Role(StrEnum):
    ADMIN = "admin"
    PM = "pm"
    DESIGNER = "designer"
    AUDITOR = "auditor"
    VIEWER = "viewer"


ROLE_HIERARCHY = {
    Role.ADMIN: {Role.ADMIN, Role.PM, Role.DESIGNER, Role.AUDITOR, Role.VIEWER},
    Role.PM: {Role.PM, Role.DESIGNER, Role.AUDITOR, Role.VIEWER},
    Role.DESIGNER: {Role.DESIGNER, Role.VIEWER},
    Role.AUDITOR: {Role.AUDITOR, Role.VIEWER},
    Role.VIEWER: {Role.VIEWER},
}


def role_includes(user_role: Role, required: Role) -> bool:
    return required in ROLE_HIERARCHY.get(user_role, set())

